def investigate(context, acquire):
    events = context.get('events', [])
    count = 0
    status = 'open'
    pending = []

    def valid_prefix(bs):
        n = len(bs)
        i = 0
        total = 0
        while i < n:
            b = bs[i]
            if b < 128:
                i += 1
                total += 1
            elif b < 192:
                return total, False
            elif b < 224:
                if i + 1 >= n:
                    return total, True
                if bs[i + 1] < 128 or bs[i + 1] > 191:
                    return total, False
                i += 2
                total += 1
            elif b < 240:
                if i + 1 >= n:
                    return total, True
                if bs[i + 1] < 128 or bs[i + 1] > 191:
                    return total, False
                if i + 2 >= n:
                    return total, True
                if bs[i + 2] < 128 or bs[i + 2] > 191:
                    return total, False
                if b == 224 and bs[i + 1] < 160:
                    return total, False
                if b == 237 and bs[i + 1] > 159:
                    return total, False
                i += 3
                total += 1
            elif b < 248:
                if i + 1 >= n:
                    return total, True
                if bs[i + 1] < 128 or bs[i + 1] > 191:
                    return total, False
                if i + 2 >= n:
                    return total, True
                if bs[i + 2] < 128 or bs[i + 2] > 191:
                    return total, False
                if i + 3 >= n:
                    return total, True
                if bs[i + 3] < 128 or bs[i + 3] > 191:
                    return total, False
                if b == 240 and bs[i + 1] < 144:
                    return total, False
                if b == 244 and bs[i + 1] > 143:
                    return total, False
                i += 4
                total += 1
            else:
                return total, False
        return total, True

    for event in events:
        op = event.get('op')
        if op == 'feed':
            if status != 'open':
                continue
            bs = list(event.get('bytes', []))
            combined = pending + bs
            total, complete = valid_prefix(combined)
            if complete:
                count += total
                pending = []
            else:
                status = 'error'
                pending = []
        elif op == 'finish':
            if status != 'open':
                continue
            if len(pending) == 0:
                status = 'finished'
            else:
                status = 'error'
                pending = []
        elif op == 'reset':
            count = 0
            status = 'open'
            pending = []
    return {'count': count, 'status': status}
